-- A bounded JSON Schema interpreter keeps direct RPC writes subject to the same data-only contract.
create function mathin_internal.experience_schema_valid(v jsonb,s jsonb,depth integer default 0) returns boolean
language plpgsql immutable set search_path=public,pg_temp as $$
declare k text; child jsonb; n integer;
begin
  if depth>32 or v is null then return false; end if;
  if s ? 'const' and v is distinct from s->'const' then return false; end if;
  if s ? 'enum' and not exists(select 1 from jsonb_array_elements(s->'enum') e where e=v) then return false; end if;
  if s ? 'anyOf' and not exists(select 1 from jsonb_array_elements(s->'anyOf') e where mathin_internal.experience_schema_valid(v,e,depth+1)) then return false; end if;
  if s ? 'oneOf' and (select count(*) from jsonb_array_elements(s->'oneOf') e where mathin_internal.experience_schema_valid(v,e,depth+1))<>1 then return false; end if;
  if s ? 'type' then
    if s->>'type'='integer' then
      if jsonb_typeof(v)<>'number' or (v::text)::numeric<>trunc((v::text)::numeric) then return false; end if;
    elsif jsonb_typeof(v) is distinct from s->>'type' then return false; end if;
  end if;
  case jsonb_typeof(v)
    when 'object' then
      if v->>'id' in ('__proto__','prototype','constructor') then return false; end if;
      if exists(select 1 from jsonb_array_elements_text(coalesce(s->'required','[]')) r where not(v ? r)) then return false; end if;
      for k,child in select * from jsonb_each(v) loop
        if k in ('__proto__','prototype','constructor') then return false; end if;
        if s->'properties' ? k then
          if not mathin_internal.experience_schema_valid(child,s->'properties'->k,depth+1) then return false; end if;
        elsif s->'additionalProperties'='false' then return false; end if;
      end loop;
    when 'array' then
      n:=jsonb_array_length(v);
      if n>coalesce((s->>'maxItems')::integer,1000) or n<coalesce((s->>'minItems')::integer,0) then return false; end if;
      if s ? 'items' and exists(select 1 from jsonb_array_elements(v) e where not mathin_internal.experience_schema_valid(e,s->'items',depth+1)) then return false; end if;
      -- All named collections use stable, unique identifiers.
      if s#>>'{items,type}'='object' and s#>'{items,properties,id}' is not null
        and n<>(select count(distinct e->>'id') from jsonb_array_elements(v) e) then return false; end if;
    when 'string' then
      if char_length(v#>>'{}')>coalesce((s->>'maxLength')::integer,16000)
        or s ? 'pattern' and (v#>>'{}') !~ (s->>'pattern') then return false; end if;
    when 'number' then
      if s ? 'minimum' and (v::text)::numeric<(s->>'minimum')::numeric
        or s ? 'maximum' and (v::text)::numeric>(s->>'maximum')::numeric then return false; end if;
    else null;
  end case;
  return true;
exception when others then return false;
end $$;

