do $copy$ begin
  execute replace(pg_get_functiondef('mathin_internal.valid_miniapp_settings(jsonb)'::regprocedure),
    'mathin_internal.valid_miniapp_settings(', 'mathin_internal.valid_miniapp_settings_before_experience(');
  execute replace(pg_get_functiondef('mathin_internal.valid_miniapp_presentation_settings(jsonb)'::regprocedure),
    '''privacy'',''document''', '''privacy'',''document'',''page'',''offering'',''catalog'',''form'',''web''');
  execute replace(pg_get_functiondef('public.save_miniapp_settings(jsonb,integer,boolean)'::regprocedure),
    'public.save_miniapp_settings(', 'mathin_internal.save_miniapp_settings_before_experience(');
  execute replace(pg_get_functiondef('public.can_access_miniapp_content_image(text,boolean)'::regprocedure),
    'public.can_access_miniapp_content_image(', 'mathin_internal.can_access_miniapp_content_image_before_experience(');
end $copy$;
create or replace function mathin_internal.valid_miniapp_settings(p jsonb) returns boolean
language sql immutable security definer set search_path=public,pg_temp as $$
  select coalesce(mathin_internal.valid_miniapp_settings_before_experience(p-'experience') and octet_length(p::text)<=1126400
    and (not(p ? 'experience') or mathin_internal.experience_schema_valid(p->'experience',mathin_internal.miniapp_experience_schema())),false);
$$;
create function mathin_internal.experience_images(p jsonb) returns setof text
language sql immutable set search_path=public,pg_temp as $$
  with recursive nodes(v) as (select p union all
    select e.value from nodes n cross join lateral (
      select value from jsonb_each(case when jsonb_typeof(n.v)='object' then n.v else '{}' end)
      union all select value from jsonb_array_elements(case when jsonb_typeof(n.v)='array' then n.v else '[]' end)
    ) e)
  select distinct v->>'image' from nodes where jsonb_typeof(v)='object' and v->>'image' ~ '^[0-9a-f-]{36}\.webp$';
$$;
create or replace function public.save_miniapp_settings(p_config jsonb,p_revision integer,p_publish boolean) returns jsonb
language plpgsql security definer set search_path=public,pg_temp as $$
declare path text;
begin
  if not coalesce(public.has_perm(auth.uid(),'organization.profile.manage'),false) then raise exception 'FORBIDDEN'; end if;
  if not mathin_internal.valid_miniapp_settings(p_config) then raise exception 'VALIDATION'; end if;
  for path in select * from mathin_internal.experience_images(p_config->'experience') loop
    if not exists(select 1 from storage.objects where bucket_id='miniapp-content-images' and name=path) then raise exception 'VALIDATION'; end if;
  end loop;
  return mathin_internal.save_miniapp_settings_before_experience(p_config,p_revision,p_publish);
end $$;
create function mathin_internal.experience_manifest(p jsonb) returns jsonb
language sql immutable set search_path=public,pg_temp as $$
  select case when p is null then null else p||jsonb_build_object(
    'pages',coalesce((select jsonb_agg(v||'{"blocks":[]}') from jsonb_array_elements(p->'pages') v where v->'enabled'='true' and v->>'audience'='all'),'[]'),
    'forms',coalesce((select jsonb_agg(v||'{"groups":[]}') from jsonb_array_elements(p->'forms') v where v->'enabled'='true' and v->>'audience'='all'),'[]'),
    'services',coalesce((select jsonb_agg(v) from jsonb_array_elements(p->'services') v where v->'enabled'='true'),'[]'),
    'destinations',coalesce((select jsonb_agg(v) from jsonb_array_elements(p->'destinations') v where v->'enabled'='true'),'[]'),
    'resources',coalesce((select jsonb_agg(v) from jsonb_array_elements(p->'resources') v where v->'enabled'='true'),'[]'),
    'notifications','[]'::jsonb) end;
$$;
create or replace function public.miniapp_settings_publication() returns jsonb
language sql stable security definer set search_path=public,pg_temp as $$
  select coalesce((select jsonb_build_object('revision',coalesce(published_revision,0),'publishedAt',published_at,'config',
    (published-'contacts')||case when published ? 'experience' then jsonb_build_object('experience',mathin_internal.experience_manifest(published->'experience')) else '{}' end)
    from miniapp_settings where singleton),jsonb_build_object('revision',0,'publishedAt',null,'config',null));
$$;
create function mathin_internal.experience_audience(p text) returns boolean
language sql stable security definer set search_path=public,pg_temp as $$
  select p='all' or (auth.uid() is not null and exists(select 1 from profiles where id=auth.uid() and is_active and account_status='active' and not password_change_required)
    and public.has_current_required_consents(auth.uid()) and (p='signedIn' or p='participants'
      and exists(select 1 from students s where public.miniapp_can_participate(s.id))));
$$;
create function public.miniapp_experience_document(p_kind text,p_id text) returns jsonb
language plpgsql stable security definer set search_path=public,pg_temp as $$
declare c jsonb; d jsonb; revision integer;
begin
  if p_kind not in ('page','form','service','web') or p_id is null or p_id !~ '^[a-zA-Z0-9_-]{1,64}$' then raise exception 'VALIDATION'; end if;
  select published->'experience',published_revision into c,revision from miniapp_settings where singleton;
  select v into d from jsonb_array_elements(c->case p_kind when 'page' then 'pages' when 'form' then 'forms' when 'service' then 'services' else 'destinations' end) v
    where v->>'id'=p_id and v->'enabled'='true';
  if d is null then raise exception 'NOT_FOUND'; end if;
  if not mathin_internal.experience_audience(coalesce(d->>'audience','all')) then raise exception 'FORBIDDEN'; end if;
  return jsonb_build_object('revision',revision,'document',d);
end $$;
create or replace function public.can_access_miniapp_content_image(p_path text,p_write boolean default false) returns boolean
language plpgsql stable security definer set search_path=public,pg_temp as $$
declare c jsonb; base text;
begin
  if mathin_internal.can_access_miniapp_content_image_before_experience(p_path,p_write) then return true; end if;
  if p_write is distinct from false or p_path is null or p_path !~ '^[0-9a-f-]{36}(\.thumb)?\.webp$' then return false; end if;
  base:=replace(p_path,'.thumb.webp','.webp');
  select published->'experience' into c from miniapp_settings where singleton;
  return exists(select 1 from jsonb_array_elements(c->'pages') p where p->'enabled'='true' and mathin_internal.experience_audience(p->>'audience')
      and base in (select * from mathin_internal.experience_images(p)))
    or exists(select 1 from jsonb_array_elements(c->'services') s where s->'enabled'='true' and s->>'image'=base)
    or exists(select 1 from jsonb_array_elements(c->'resources') r where r->'enabled'='true' and r->>'image'=base);
end $$;
revoke all on function mathin_internal.experience_schema_valid(jsonb,jsonb,integer),mathin_internal.miniapp_experience_schema(),
  mathin_internal.valid_miniapp_settings_before_experience(jsonb),mathin_internal.save_miniapp_settings_before_experience(jsonb,integer,boolean),
  mathin_internal.can_access_miniapp_content_image_before_experience(text,boolean),mathin_internal.experience_images(jsonb),mathin_internal.experience_manifest(jsonb),
  mathin_internal.experience_audience(text),public.miniapp_experience_document(text,text) from public,anon,authenticated;
grant execute on function public.miniapp_experience_document(text,text) to anon,authenticated;
notify pgrst,'reload schema';
commit;
